'use strict';

(function () {
  const TOPIC = 'chapter-15';
  const PREFIX = 'ch15';

  const base = (kitRef, type, text, en, ru, uz) => ({ id: `${PREFIX}-q${kitRef}`, kitRef, topicId: TOPIC, type, text, explanation: { en, ru, uz } });
  const single = (kitRef, text, options, correctIndex, en, ru, uz, extra = {}) => ({ ...base(kitRef, 'single', text, en, ru, uz), options, correctIndex, ...extra });
  const number = (kitRef, text, correctValue, answerText, en, ru, uz, extra = {}) => ({ ...base(kitRef, 'number', text, en, ru, uz), correctValue, answerText, ...extra });
  const matrix = (kitRef, text, columns, rows, en, ru, uz) => ({ ...base(kitRef, 'matrix', text, en, ru, uz), columns, rows });
  const multi = (kitRef, text, options, correctIndices, en, ru, uz) => ({ ...base(kitRef, 'multi', text, en, ru, uz), options, correctIndices });
  const TF = ['True', 'False'];
  const T = 0;
  const F = 1;

  const questions = [
    single(368, 'A sole trader had net assets of $22,000 at 30 April 20X7. In the year to that date the trader introduced $11,200 of capital, made a profit of $9,500 and withdrew $4,700. What was the capital balance at 1 May 20X6?',
      ['$6,000', '$15,500', '$17,200', '$38,000'], 0,
      `Opening + capital introduced + profit - drawings = closing net assets. So opening = $22,000 - $11,200 - $9,500 + $4,700 = $6,000.`,
      `На начало + внесённый капитал + прибыль - изъятия = чистые активы на конец. Значит, на начало = $22,000 - $11,200 - $9,500 + $4,700 = $6,000.`,
      `Boshlang'ich + kiritilgan kapital + foyda - olib qo'yishlar = yakuniy sof aktivlar. Demak boshlang'ich = $22,000 - $11,200 - $9,500 + $4,700 = $6,000.`),
    multi(369, 'Which TWO of these are advantages of a bonus issue of shares?',
      ['It is the cheapest way to raise finance through issuing shares', 'It makes the company\'s shares more marketable', 'The total of retained earnings and other components of equity will increase', 'Share capital is brought more into line with the assets employed'], [1, 3],
      `A bonus issue raises no finance at all. More shares mean a lower price per share, which helps marketability, and capital moves closer to assets employed. Reserves fall rather than rise.`,
      `Бонусный выпуск вообще не привлекает финансирование. Больше акций — ниже цена акции, это улучшает ликвидность, а капитал приближается к используемым активам. Резервы падают, а не растут.`,
      `Bonusli chiqarish umuman moliya jalb qilmaydi. Ko'proq aksiya — past narx, bu sotilishni yaxshilaydi, kapital ishlatilayotgan aktivlarga yaqinlashadi. Rezervlar oshmaydi, kamayadi.`),
    single(370, 'A hairdresser\'s records for the year show: expenses $8,300; opening inventory $1,800; closing inventory $1,100; purchases $14,200; gross profit $13,000; inventory taken as drawings $90. What was revenue?',
      ['$27,810', '$27,900', '$27,990', '$36,110'], 0,
      `Goods taken by the owner are not a cost of sales. Cost of sales is $1,800 + $14,200 - $90 - $1,100 = $14,810. Revenue is $14,810 + $13,000 = $27,810. Expenses come after gross profit, so ignore them.`,
      `Товар, взятый владельцем, не себестоимость. Себестоимость: $1,800 + $14,200 - $90 - $1,100 = $14,810. Выручка: $14,810 + $13,000 = $27,810. Расходы идут после валовой прибыли, их не учитываем.`,
      `Egasi olgan tovar tannarx emas. Tannarx: $1,800 + $14,200 - $90 - $1,100 = $14,810. Tushum: $14,810 + $13,000 = $27,810. Xarajatlar yalpi foydadan keyin keladi, e'tiborga olinmaydi.`),
    single(371, 'A company\'s trial balance includes a debit balance of $600 on income tax. It estimates income tax payable for the year at $9,000. What amounts go in the financial statements?',
      ['Profit or loss $9,000; financial position $9,000', 'Profit or loss $9,600; financial position $9,000', 'Profit or loss $8,400; financial position $9,600', 'Profit or loss $9,000; financial position $8,400'], 1,
      `A debit balance is last year's underprovision, so it adds to this year's expense: $9,600. The liability is only this year's estimate: $9,000.`,
      `Дебетовый остаток — недоначисление прошлого года, он добавляется к расходу этого года: $9,600. Обязательство — только оценка этого года: $9,000.`,
      `Debet qoldiq o'tgan yil kam hisoblangani, shu yil xarajatiga qo'shiladi: $9,600. Majburiyat faqat shu yil bahosi: $9,000.`),
    single(372, 'Which of these would change the capital of a business?',
      ['Buying raw materials on credit', 'Paying wages in cash', 'Buying non-current assets on credit', 'Making a bank payment to a supplier'], 1,
      `Capital equals net assets. Wages reduce assets with nothing gained, so profit and capital fall. The others either swap assets and liabilities or change both equally.`,
      `Капитал равен чистым активам. Зарплата уменьшает активы без приобретения, поэтому прибыль и капитал падают. Остальные меняют активы и обязательства одинаково.`,
      `Kapital sof aktivlarga teng. Ish haqi aktivlarni hech narsasiz kamaytiradi, foyda va kapital tushadi. Qolganlari aktiv va majburiyatlarni teng o'zgartiradi.`),
    single(373, 'A draft statement of financial position shows a loan repayable 14 months after the reporting date within trade payables. What will the correction do?',
      ['Have no effect on net current assets', 'Increase net current assets', 'Reduce net current assets', 'Increase current assets but reduce net current assets'], 1,
      `A loan due after 14 months is non-current. Moving it out of trade payables reduces current liabilities, so net current assets rise. Current assets do not change.`,
      `Кредит со сроком 14 месяцев долгосрочный. Перенос из кредиторов уменьшает краткосрочные обязательства, поэтому чистые оборотные активы растут. Оборотные активы не меняются.`,
      `14 oydan keyingi kredit uzoq muddatli. Uni kreditorlardan ko'chirish qisqa muddatli majburiyatlarni kamaytiradi, sof aylanma aktivlar oshadi. Aylanma aktivlar o'zgarmaydi.`),
    single(374, 'Which formula gives the profit of a business?',
      ['Opening capital - drawings + capital introduced - closing capital', 'Opening capital + drawings - capital introduced - closing capital', 'Closing capital - drawings + capital introduced - opening capital', 'Closing capital + drawings - capital introduced - opening capital'], 3,
      `Profit is the rise in capital in the period, after putting back what the owner took out and removing what the owner put in.`,
      `Прибыль — рост капитала за период, если вернуть то, что владелец забрал, и убрать то, что он внёс.`,
      `Foyda davrdagi kapital o'sishi, egasi olganini qaytarib, kiritganini olib tashlagandan keyin.`),
    single(375, 'Which concept requires goods taken from inventory by the owner to be treated as drawings?',
      ['Prudence', 'Separate entity', 'Accruals', 'Substance over form'], 1,
      `The accounts report the business, not its owner. Goods taken for private use have left the business, so they are drawings.`,
      `Отчётность показывает бизнес, а не владельца. Товар для личных нужд ушёл из бизнеса, поэтому это изъятия.`,
      `Hisobot biznesni ko'rsatadi, egasini emas. Shaxsiy maqsadda olingan tovar biznesdan chiqdi, shuning uchun olib qo'yish.`),
    number(376, 'A company had a revaluation surplus of $85,000 on land and buildings in the year. Depreciation on buildings was $24,000, and it does not transfer excess depreciation. There was also a $1,200 gain on disposal of vehicles. What is included in other comprehensive income?', 85000, '$85,000',
      `Only the revaluation gain is in other comprehensive income. Depreciation and the disposal gain belong in profit or loss.`,
      `В прочий совокупный доход входит только прирост от переоценки. Амортизация и прибыль от выбытия — в прибыли или убытке.`,
      `Boshqa umumlashgan daromadga faqat qayta baholash foydasi kiradi. Amortizatsiya va chiqish foydasi foyda yoki zararda.`),
    single(377, 'Use the details below at 30 September 20X6. The loan is repayable in four equal annual instalments starting on 1 January 20X7. What are current assets and current liabilities?',
      ['Current assets $38,770; current liabilities $39,100', 'Current assets $42,370; current liabilities $35,500', 'Current assets $42,370; current liabilities $65,500', 'Current assets $38,770; current liabilities $69,100'], 3,
      `Current assets: $26,400 - $1,700 + $13,900 + $170 = $38,770. A debit on a bank statement is an overdraft, so it is a liability. Current liabilities: $3,600 + $34,200 + $1,300 + the $30,000 first instalment = $69,100.`,
      `Оборотные активы: $26,400 - $1,700 + $13,900 + $170 = $38,770. Дебет в выписке — овердрафт, это обязательство. Краткосрочные: $3,600 + $34,200 + $1,300 + первый платёж $30,000 = $69,100.`,
      `Aylanma aktivlar: $26,400 - $1,700 + $13,900 + $170 = $38,770. Ko'chirmadagi debet overdraft, bu majburiyat. Qisqa muddatli: $3,600 + $34,200 + $1,300 + birinchi to'lov $30,000 = $69,100.`,
      { table: { head: ['Item', '$'], rows: [['Motor van', '16,000'], ['Loan', '120,000'], ['Receivables', '26,400'], ['Bank balance (a debit on the bank statement)', '3,600'], ['Accumulated depreciation', '8,000'], ['Payables', '34,200'], ['Inventory', '13,900'], ['Petty cash', '170'], ['Rent due', '1,300'], ['Allowance for receivables', '1,700']] } }),
    single(378, 'At the start of a week a business had assets of $18,400 and liabilities of $12,900. In the week: goods for resale were bought on credit for $350; the owner put in $1,600 of long-term capital; rent of $800 was paid; the owner withdrew $450 in cash; and goods that cost $700 were sold on credit for $1,300. What is capital at the end of the week?',
      ['$6,450', '$5,850', '$1,600', '$950'], 0,
      `Opening capital is $18,400 - $12,900 = $5,500. Add $1,600, less rent $800, less drawings $450, plus the profit on sale of $600 = $6,450. The credit purchase changes nothing.`,
      `Капитал на начало: $18,400 - $12,900 = $5,500. Плюс $1,600, минус аренда $800, минус изъятия $450, плюс прибыль от продажи $600 = $6,450. Закупка в кредит ничего не меняет.`,
      `Boshlang'ich kapital: $18,400 - $12,900 = $5,500. Plus $1,600, minus ijara $800, minus olib qo'yish $450, plus sotuv foydasi $600 = $6,450. Nasiya xarid hech narsani o'zgartirmaydi.`),
    number(379, 'A company incurred development expenditure of $60,000, which meets the capitalisation criteria. Amortisation of intangibles was $18,000, and there was a loss on disposal of plant of $3,500. What is the total expense in profit or loss?', 21500, '$21,500',
      `The development spending is capitalised, so it is not an expense. The expense is $18,000 + $3,500 = $21,500.`,
      `Затраты на разработку капитализируются, это не расход. Расход: $18,000 + $3,500 = $21,500.`,
      `Ishlanma xarajatlari kapitallashtiriladi, xarajat emas. Xarajat: $18,000 + $3,500 = $21,500.`),
    number(380, 'On 1 January a company revalued a property to $120,000. It had cost $90,000 and had accumulated depreciation of $18,000. Its useful life was 50 years from purchase, with no residual value. What excess depreciation could be transferred at 31 December?', 1200, '$1,200',
      `The old charge is $90,000 / 50 = $1,800, so the property is 10 years old with 40 left. The new charge is $120,000 / 40 = $3,000. The excess is $3,000 - $1,800 = $1,200.`,
      `Прежнее начисление $90,000 / 50 = $1,800, значит, зданию 10 лет, осталось 40. Новое $120,000 / 40 = $3,000. Превышение $3,000 - $1,800 = $1,200.`,
      `Eski summa $90,000 / 50 = $1,800, demak mulk 10 yoshda, 40 yil qolgan. Yangi $120,000 / 40 = $3,000. Ortiqcha $3,000 - $1,800 = $1,200.`),
    multi(381, 'In which TWO financial statements would you expect to find dividends paid?',
      ['Statement of profit or loss and other comprehensive income', 'Statement of financial position', 'Statement of cash flows', 'Statement of changes in equity'], [2, 3],
      `Dividends paid are cash leaving the business, so they are in the statement of cash flows. They also reduce equity, so they are in the statement of changes in equity.`,
      `Выплаченные дивиденды — уходящие деньги, они в отчёте о движении денег. Они также уменьшают капитал, поэтому есть в отчёте об изменениях капитала.`,
      `To'langan dividendlar chiqayotgan pul, pul oqimlari hisobotida. Ular kapitalni ham kamaytiradi, kapital o'zgarishlari hisobotida.`),
    single(382, 'A company revalued a property to $240,000. It had cost $190,000 and had accumulated depreciation of $50,000. What entries record the revaluation?',
      ['Dr Property $240,000, Cr Revaluation surplus $240,000', 'Dr Revaluation surplus $100,000, Cr Property $50,000, Cr Accumulated depreciation $50,000', 'Dr Property $50,000, Cr Revaluation surplus $50,000', 'Dr Property $50,000, Dr Accumulated depreciation $50,000, Cr Revaluation surplus $100,000'], 3,
      `The carrying amount is $140,000, so the surplus is $240,000 - $140,000 = $100,000. The asset rises by $50,000 to the valuation, and the $50,000 of accumulated depreciation is cleared.`,
      `Балансовая стоимость $140,000, резерв $240,000 - $140,000 = $100,000. Актив растёт на $50,000 до оценки, а накопленная амортизация $50,000 обнуляется.`,
      `Balans qiymati $140,000, rezerv $240,000 - $140,000 = $100,000. Aktiv bahogacha $50,000 oshadi, $50,000 to'plangan amortizatsiya nolga tushadi.`),
    single(383, 'A company has $120,000 of $0.50 equity shares and $500,000 of 6% irredeemable preference shares in issue. In the year it paid a dividend of 4 cents per equity share and half of the preference dividend. Which statements are true? (1) An equity dividend of $4,800 was paid. (2) A preference dividend of $15,000 was accrued at the year end.',
      ['1 only', '2 only', 'Neither 1 nor 2', 'Both 1 and 2'], 1,
      `There are $120,000 / $0.50 = 240,000 shares, so the equity dividend is 240,000 x 4c = $9,600, and statement 1 is false. The preference dividend is $30,000 for the year, so $15,000 unpaid is accrued.`,
      `Акций $120,000 / $0.50 = 240,000, дивиденд 240,000 x 4c = $9,600, утверждение 1 неверно. Привилегированный дивиденд $30,000 в год, поэтому неуплаченные $15,000 начисляются.`,
      `Aksiyalar $120,000 / $0.50 = 240,000, dividend 240,000 x 4c = $9,600, 1-bayonot noto'g'ri. Imtiyozli dividend yiliga $30,000, to'lanmagan $15,000 hisoblanadi.`),
    single(384, 'Where should income tax expense for the period and a gain on revaluation of a non-current asset be presented?',
      ['Tax: statement of changes in equity. Gain: statement of profit or loss and other comprehensive income', 'Tax: statement of profit or loss and other comprehensive income. Gain: statement of cash flows', 'Both in the statement of profit or loss and other comprehensive income', 'Both in the statement of cash flows'], 2,
      `Income tax expense is in profit or loss. A revaluation gain is in other comprehensive income. Both are parts of the same statement. A revaluation involves no cash.`,
      `Расход по налогу — в прибыли или убытке. Прирост от переоценки — в прочем совокупном доходе. Оба — части одного отчёта. Переоценка не связана с деньгами.`,
      `Soliq xarajati foyda yoki zararda. Qayta baholash foydasi boshqa umumlashgan daromadda. Ikkalasi bitta hisobot qismi. Qayta baholash pul bilan bog'liq emas.`),
    single(385, 'Use the figures below. Depreciation is split 70:30 between the factory and the office, and office costs are general and administrative expenses. What is cost of sales?',
      ['$239,800', '$243,700', '$251,800', '$258,700'], 1,
      `Cost of sales is opening inventory $13,400 + purchases $210,000 + carriage in $3,900 + factory depreciation $35,000 - closing inventory $18,600 = $243,700. Carriage out and the audit fee are not part of it.`,
      `Себестоимость: запасы на начало $13,400 + закупки $210,000 + доставка закупок $3,900 + амортизация завода $35,000 - запасы на конец $18,600 = $243,700. Доставка продаж и аудит сюда не входят.`,
      `Tannarx: boshlang'ich zaxira $13,400 + xaridlar $210,000 + kelish tashuvi $3,900 + zavod amortizatsiyasi $35,000 - yakuniy zaxira $18,600 = $243,700. Ketish tashuvi va audit kirmaydi.`,
      { table: { head: ['Item', '$'], rows: [['Opening inventory', '13,400'], ['Closing inventory', '18,600'], ['Purchases', '210,000'], ['Selling expenses', '38,000'], ['General and administrative expenses', '82,000'], ['Audit fee', '16,000'], ['Carriage in', '3,900'], ['Carriage out', '8,100'], ['Depreciation', '50,000']] } }),
    single(386, 'At the start of the year a company had equity shares of $0.25 with a total nominal value of $120,000, and share premium of $40,000. It made a 1-for-4 rights issue at $1.25, fully taken up, followed by a 1-for-10 bonus issue. What is the balance on share premium after these?',
      ['$25,000', '$28,000', '$145,000', '$160,000'], 2,
      `There are 480,000 shares. The rights issue adds 120,000 shares, each with a $1.00 premium: $160,000. The bonus issue on 600,000 shares creates 60,000 shares, using 60,000 x $0.25 = $15,000 of premium. $160,000 - $15,000 = $145,000.`,
      `Акций 480,000. Выпуск прав добавляет 120,000 акций с премией $1.00: $160,000. Бонус на 600,000 акций создаёт 60,000 акций и использует 60,000 x $0.25 = $15,000 премии. $160,000 - $15,000 = $145,000.`,
      `Aksiyalar 480,000. Huquqli chiqarish 120,000 aksiya qo'shadi, har biri $1.00 mukofot: $160,000. 600,000 aksiyaga bonus 60,000 aksiya yaratadi va 60,000 x $0.25 = $15,000 mukofot ishlatadi. $160,000 - $15,000 = $145,000.`),
    single(387, 'In September 20X5 a company paid the final dividend of $110,000 for the year ended 30 June 20X5, declared in August 20X5. In March 20X6 it paid an interim dividend of $45,000. In September 20X6 it paid the final dividend of $130,000 for the year ended 30 June 20X6, declared in August 20X6. What figures appear for the year ended 30 June 20X6?',
      ['Profit or loss: $175,000 deduction. Financial position: $130,000', 'Profit or loss: $155,000 deduction. Financial position: $0', 'Profit or loss: $0. Financial position: $130,000', 'Profit or loss: $0. Financial position: $0'], 3,
      `Dividends are never an expense in profit or loss. The final dividend was declared after the year end, so there is no liability at 30 June 20X6.`,
      `Дивиденды никогда не расход в прибыли или убытке. Итоговый дивиденд объявлен после конца года, поэтому обязательства на 30 июня 20X6 нет.`,
      `Dividendlar foyda yoki zararda hech qachon xarajat emas. Yakuniy dividend yil oxiridan keyin e'lon qilingan, 30 iyun 20X6 da majburiyat yo'q.`),
    matrix(388, 'State whether each statement is true or false.', TF, [
      { text: 'A company may make a rights issue to raise more equity capital', correctIndex: T },
      { text: 'A rights issue might increase share premium, whereas a bonus issue is likely to reduce it', correctIndex: T },
      { text: 'A rights issue will always increase the number of shareholders, whereas a bonus issue will not', correctIndex: F },
      { text: 'A bonus issue will increase the market value of each share', correctIndex: F },
    ],
      `A rights issue brings in cash, usually above nominal value, so premium rises. A bonus issue is usually funded from premium. Both go to existing shareholders, so the number of holders does not rise, and more shares make each worth less.`,
      `Выпуск прав приносит деньги, обычно выше номинала, премия растёт. Бонус обычно покрывается из премии. Оба идут существующим акционерам, их число не растёт, а больше акций снижает цену каждой.`,
      `Huquqli chiqarish pul olib keladi, odatda nominaldan yuqori, mukofot oshadi. Bonus odatda mukofotdan. Ikkalasi mavjud aksiyadorlarga, ularning soni oshmaydi, ko'proq aksiya har birini arzonlashtiradi.`),
    single(389, 'A trial balance includes a credit balance of $4,100 on income tax, after last year\'s liability was settled. Tax on this year\'s profits is estimated at $72,500. What amounts go in the financial statements?',
      ['Expense $72,500; payable $72,500', 'Expense $68,400; payable $68,400', 'Expense $68,400; payable $72,500', 'Expense $76,600; payable $72,500'], 2,
      `A credit balance is an overprovision, so it reduces this year's expense: $72,500 - $4,100 = $68,400. The liability is the full estimate of $72,500.`,
      `Кредитовый остаток — переначисление, он уменьшает расход: $72,500 - $4,100 = $68,400. Обязательство — полная оценка $72,500.`,
      `Kredit qoldiq ko'p hisoblangani, xarajatni kamaytiradi: $72,500 - $4,100 = $68,400. Majburiyat to'liq baho $72,500.`),
    matrix(390, 'Classify each item as current or non-current.', ['Current', 'Non-current'], [
      { text: 'A credit sale to a customer who has agreed to pay in 12 months', correctIndex: 0 },
      { text: 'A bank overdraft facility of $30,000 available for the next three years', correctIndex: 0 },
      { text: 'A small number of shares in another entity bought in order to trade them', correctIndex: 0 },
      { text: 'A bank loan with a repayment date five years away', correctIndex: 1 },
    ],
      `A credit sale is part of the operating cycle. An overdraft is repayable on demand, whatever the facility length. Shares held to trade are current. Only the five-year loan is non-current.`,
      `Продажа в кредит — часть операционного цикла. Овердрафт погашается по требованию при любом сроке лимита. Акции для торговли оборотные. Долгосрочный только кредит на пять лет.`,
      `Nasiya sotuv operatsion sikl qismi. Overdraft limit muddatidan qat'i nazar talab bo'yicha to'lanadi. Savdo uchun aksiyalar aylanma. Faqat besh yillik kredit uzoq muddatli.`),
    single(391, 'A company\'s records for the year show: revaluation gain in the year $240,000; equity interim dividend paid $14,000; profit before income taxes $190,000; estimated income tax $48,000; 8% $1 redeemable preference shares $120,000; underprovision for tax in the previous year $6,000; proceeds of an issue of 3,000 $1 equity shares $7,500; final equity dividend proposed $28,000. What is the total increase in equity for the year in the statement of changes in equity?',
      ['$341,500', '$362,000', '$369,500', '$375,500'], 2,
      `Profit after tax is $190,000 - $48,000 - $6,000 = $136,000. Add the share issue $7,500 and the revaluation $240,000, and deduct the $14,000 dividend paid: $369,500. Redeemable shares are a liability, and the proposed dividend is not yet recorded.`,
      `Прибыль после налога: $190,000 - $48,000 - $6,000 = $136,000. Плюс выпуск $7,500 и переоценка $240,000, минус выплаченный дивиденд $14,000: $369,500. Погашаемые акции — обязательство, а предложенный дивиденд ещё не записан.`,
      `Soliqdan keyingi foyda: $190,000 - $48,000 - $6,000 = $136,000. Plus chiqarish $7,500 va qayta baholash $240,000, minus to'langan $14,000 dividend: $369,500. Qaytariladigan aksiyalar majburiyat, taklif qilingan dividend hali yozilmagan.`),
    single(392, 'Which statements about a preference share are true? (1) They carry voting rights. (2) Their dividend is paid in priority to an equity dividend. (3) Their dividend is related to profits.',
      ['1, 2 and 3', '1 and 2 only', '2 and 3 only', '2 only'], 3,
      `Preference shares generally carry no vote, and their dividend is a fixed percentage of nominal value, not linked to profits. They are paid ahead of equity dividends.`,
      `Привилегированные акции обычно без голоса, их дивиденд — фиксированный процент от номинала, не связанный с прибылью. Он платится раньше обыкновенных.`,
      `Imtiyozli aksiyalar odatda ovozsiz, dividendi nominalning qat'iy foizi, foydaga bog'liq emas. U oddiy dividenddan oldin to'lanadi.`),
    single(393, 'A company issues 120,000 4% $1 redeemable preference shares at 97 cents each. What are the correct entries?',
      ['Dr Cash $116,400, Cr Liability $116,400', 'Dr Cash $116,400, Cr Share capital $120,000, Cr Share premium $3,600', 'Dr Cash $116,400, Cr Share capital $116,400', 'Dr Cash $116,400, Dr Profit or loss $3,600, Cr Share capital $120,000'], 0,
      `Redeemable preference shares must be repaid, so in substance they are debt. The cash received of 120,000 x 97c = $116,400 is recorded as a liability.`,
      `Погашаемые привилегированные акции нужно вернуть, по сути это долг. Полученные 120,000 x 97c = $116,400 записываются как обязательство.`,
      `Qaytariladigan imtiyozli aksiyalar qaytarilishi kerak, mohiyatan qarz. Olingan 120,000 x 97c = $116,400 majburiyat sifatida yoziladi.`),
    single(394, 'Which items in the statement of financial position change immediately after a bonus issue funded from retained earnings?',
      ['Share capital and cash', 'Share capital and retained earnings', 'Share premium and cash', 'Share premium and retained earnings'], 1,
      `A bonus issue brings in no cash. Here it moves an amount out of retained earnings and into share capital.`,
      `Бонусный выпуск не приносит денег. Здесь сумма переходит из нераспределённой прибыли в акционерный капитал.`,
      `Bonusli chiqarish pul olib kelmaydi. Bu yerda summa taqsimlanmagan foydadan aksiya kapitaliga o'tadi.`),
    single(395, 'A company issued $500,000 of 12% loan notes for $475,000 on 1 August. What entries are needed in the year ended 30 September?',
      ['Dr Bank $500,000, Cr Non-current liabilities $500,000; Dr Interest $9,500, Cr Current liabilities $9,500', 'Dr Bank $475,000, Cr Non-current liabilities $475,000; Dr Interest $10,000, Cr Current liabilities $10,000', 'Dr Bank $500,000, Cr Non-current liabilities $500,000; Dr Interest $10,000, Cr Current liabilities $10,000', 'Dr Bank $475,000, Cr Non-current liabilities $475,000; Dr Interest $9,500, Cr Current liabilities $9,500'], 1,
      `Record the cash actually received. Interest is always on nominal value: $500,000 x 12% x 2/12 = $10,000, which is accrued because it has not been paid.`,
      `Записывается фактически полученная сумма. Проценты всегда от номинала: $500,000 x 12% x 2/12 = $10,000, они начисляются, так как не выплачены.`,
      `Aslida olingan pul yoziladi. Foiz doim nominaldan: $500,000 x 12% x 2/12 = $10,000, to'lanmagani uchun hisoblanadi.`),
    single(396, 'A company\'s reserves would decrease if it did which of these?',
      ['Paid a dividend', 'Issued shares at a premium', 'Set aside profits to pay future dividends', 'Transferred an amount into a general reserve'], 0,
      `Paying a dividend takes money out of retained earnings. Transfers stay inside reserves, and a premium increases them.`,
      `Выплата дивиденда забирает деньги из нераспределённой прибыли. Переносы остаются внутри резервов, а премия их увеличивает.`,
      `Dividend to'lash taqsimlanmagan foydadan pul oladi. O'tkazmalar rezervlar ichida qoladi, mukofot esa oshiradi.`),
    matrix(397, 'A company revalued a building in the year. For each item, say where it goes in the statement of profit or loss and other comprehensive income.', ['Profit or loss', 'Other comprehensive income', 'Omitted from this statement'], [
      { text: 'Excess depreciation on revaluation of $2,500', correctIndex: 2 },
      { text: 'Increase in the carrying amount of the property of $60,000', correctIndex: 1 },
      { text: 'Depreciation charge of $15,000', correctIndex: 0 },
    ],
      `The depreciation charge is an expense. The revaluation is other comprehensive income. Excess depreciation is a transfer within equity, so it only appears in the statement of changes in equity.`,
      `Амортизация — расход. Переоценка — прочий совокупный доход. Избыточная амортизация — перенос внутри капитала, она есть только в отчёте об изменениях капитала.`,
      `Amortizatsiya xarajat. Qayta baholash boshqa umumlashgan daromad. Ortiqcha amortizatsiya kapital ichidagi o'tkazma, faqat kapital o'zgarishlari hisobotida.`),
    single(398, 'A company disposed of a revalued property. Its carrying amount was $180,000, the proceeds were $200,000, and the revaluation surplus at that date was $20,000. How is the disposal accounted for?',
      ['A gain of $20,000 in profit or loss, and $20,000 transferred from revaluation surplus to retained earnings', 'A gain of $40,000 in profit or loss only', 'A gain of $20,000 in profit or loss and a revaluation gain of $20,000 in other comprehensive income', 'A gain of $20,000 in profit or loss only'], 0,
      `The gain is $200,000 - $180,000 = $20,000. The surplus is now realised, so it moves within equity to retained earnings. It never goes through profit or loss.`,
      `Прибыль: $200,000 - $180,000 = $20,000. Резерв теперь реализован и переходит внутри капитала в нераспределённую прибыль. Через прибыль или убыток он не идёт.`,
      `Foyda: $200,000 - $180,000 = $20,000. Rezerv endi amalga oshdi va kapital ichida taqsimlanmagan foydaga o'tadi. U foyda yoki zarardan o'tmaydi.`),
    single(399, 'A business year ended on 31 August. (1) It sold a machine to a customer on 28 August, and the customer handles installation and operation after delivery. (2) It sold food mixers on credit to a customer who collected them on 26 August and has not yet paid. For which transactions is revenue recognised?',
      ['1 only', '2 only', 'Both 1 and 2', 'Neither 1 nor 2'], 2,
      `Control of the goods passed in both cases before the year end, so both obligations are satisfied. Not having been paid yet only creates a receivable.`,
      `Контроль над товаром в обоих случаях перешёл до конца года, поэтому обе обязанности исполнены. Отсутствие оплаты лишь создаёт дебитора.`,
      `Ikkala holda tovar nazorati yil oxirigacha o'tgan, ikkala majburiyat bajarilgan. To'lov yo'qligi faqat debitor yaratadi.`),
    single(400, 'A company estimated income tax payable for the year at $18,000. The tax expense in the statement of profit or loss is $17,100. Which statement is true?',
      ['The difference comes from an underprovision in the prior year', 'The difference comes from an overprovision in the prior year', 'It is not possible to tell which it is', 'There is no relationship between the two amounts'], 1,
      `The expense is lower than the liability, so something has reduced it. That is an overprovision from last year. An underprovision would have made the expense higher.`,
      `Расход ниже обязательства, значит, что-то его уменьшило. Это переначисление прошлого года. Недоначисление сделало бы расход выше.`,
      `Xarajat majburiyatdan past, demak nimadir kamaytirgan. Bu o'tgan yil ko'p hisoblangani. Kam hisoblangan xarajatni oshirardi.`),
    number(401, 'A training firm has a 31 December year end. In December: (1) twelve students paid $1,200 each in advance for a course that starts in January, made up of materials worth $240 and lectures worth $960, with materials given out on the first day; (2) it sold and delivered study materials to 50 self-study students at $300 each, with no further support. What revenue is recognised for the year?', 15000, '$15,000',
      `Nothing has been supplied to the course students yet, so their fees are deferred income. Only the self-study sales are complete: 50 x $300 = $15,000.`,
      `Студентам курса ещё ничего не поставлено, их оплата — доходы будущих периодов. Завершены только продажи для самостоятельного изучения: 50 x $300 = $15,000.`,
      `Kurs talabalariga hali hech narsa berilmagan, to'lovlari kelgusi davr daromadi. Faqat mustaqil o'qish sotuvlari tugallangan: 50 x $300 = $15,000.`),
    number(402, 'A retailer is the sole distributor of a new game. At its 31 July year end it held customer orders and deposits of $600,000. All orders will be despatched by 1 December. What revenue is recognised for the year ended 31 July?', 0, '$0',
      `Nothing has been delivered, so no obligation is satisfied. The deposits are deferred income, a current liability, until the games are despatched.`,
      `Ничего не поставлено, обязанность не исполнена. Депозиты — доходы будущих периодов, краткосрочное обязательство, до отгрузки.`,
      `Hech narsa yetkazilmagan, majburiyat bajarilmagan. Depozitlar o'yinlar yuborilguncha kelgusi davr daromadi, qisqa muddatli majburiyat.`),
    number(403, 'A cleaning firm charges each business $1,440 a year, and service is provided evenly over time. It serves 15 businesses in one block. One customer ended its agreement with effect from 31 August, and two new contracts began on 1 December. Some customers pay a month in advance and some are a month behind, the same at the start and end of the year. What revenue is recognised for the year ended 31 March?', 21720, '$21,720',
      `Revenue follows the service, not the cash. Fourteen full-year customers give $20,160. The customer that left had five months: $600. The two new ones had four months each: $960. The total is $21,720.`,
      `Выручка следует за услугой, а не за деньгами. Четырнадцать клиентов на полный год дают $20,160. Ушедший клиент — пять месяцев: $600. Два новых — по четыре месяца: $960. Всего $21,720.`,
      `Tushum pulga emas, xizmatga ergashadi. O'n to'rt to'liq yillik mijoz $20,160. Ketgan mijoz besh oy: $600. Ikki yangi to'rt oydan: $960. Jami $21,720.`),
    single(404, 'At 1 January a company had an estimated tax liability of $2,800, settled by a payment of $2,450. Because of a loss for the year it expects a tax repayment of $2,500. What amounts are included in the financial statements?',
      ['$2,850 tax expense; $2,150 receivable', '$2,500 tax income; $2,500 payable', '$2,850 tax income; $2,500 receivable', '$2,150 tax expense; $2,500 receivable'], 2,
      `The overprovision of $350 reduces tax, and the $2,500 repayment is income, so tax income is $2,850. The $2,500 due back is a receivable.`,
      `Переначисление $350 уменьшает налог, а возврат $2,500 — доход, поэтому доход по налогу $2,850. Возврат $2,500 — дебитор.`,
      `$350 ko'p hisoblangan soliqni kamaytiradi, $2,500 qaytarish daromad, soliq daromadi $2,850. Qaytariladigan $2,500 debitor.`),
    single(405, 'A company estimated its tax liability at $18,200 and settled it by paying $18,800. Having made a loss this year it expects a $5,000 repayment. What amounts are included in the financial statements?',
      ['$5,000 tax income; $5,000 payable', '$4,400 tax expense; $5,000 payable', '$5,600 tax income; $5,000 receivable', '$4,400 tax income; $5,000 receivable'], 3,
      `The underprovision of $600 is an expense. The $5,000 repayment is income, so net tax income is $4,400. The amount due back is a receivable.`,
      `Недоначисление $600 — расход. Возврат $5,000 — доход, чистый доход по налогу $4,400. Сумма к возврату — дебитор.`,
      `Kam hisoblangan $600 xarajat. $5,000 qaytarish daromad, sof soliq daromadi $4,400. Qaytariladigan summa debitor.`),
    single(406, 'Which statement gives the full definition of aggregation?',
      ['Adding together assets, liabilities, equity or cash flows that share characteristics and are in the same classification', 'Adding together assets, liabilities, equity, income and expenses, or cash flows, that share characteristics and are in the same classification', 'Adding together assets, liabilities, income and expenses or cash flows that share characteristics and are in the same classification', 'Adding together assets, liabilities, equity, income and expenses that share characteristics and are in the same classification'], 1,
      `The definition covers every element: assets, liabilities, equity, income, expenses and cash flows. Each of the other answers leaves something out.`,
      `Определение охватывает все элементы: активы, обязательства, капитал, доходы, расходы и денежные потоки. В каждом другом ответе что-то пропущено.`,
      `Ta'rif barcha elementlarni qamraydi: aktivlar, majburiyatlar, kapital, daromad, xarajat va pul oqimlari. Boshqa har bir javobda nimadir tushib qolgan.`),
    single(407, 'Which of these should be disclosed in the notes about intangible assets? (1) Accumulated amortisation at the start and end of the period. (2) A reconciliation of the movement in carrying amount. (3) A directors\' statement on whether capitalised development costs will be recovered.',
      ['1 only', '2 only', '1 and 2', '2 and 3'], 2,
      `Items 1 and 2 are normal note disclosures. Directors must be satisfied about recovery before capitalising, so no separate statement is needed.`,
      `Пункты 1 и 2 — обычные раскрытия. Директора должны быть уверены в возмещении до капитализации, поэтому отдельное заявление не нужно.`,
      `1 va 2-bandlar odatiy izohlar. Direktorlar kapitallashtirishdan oldin qoplanishiga ishonch hosil qilishi kerak, alohida bayonot kerak emas.`),
    single(408, 'Which is a suitable accounting policy note for intangible assets?',
      ['Some intangibles use the cost model and others the valuation model, as the directors judge best, and all are written off over their useful lives', 'Intangibles use the valuation model, based on the directors\' estimate, with all changes in value taken to profit or loss', 'The entity uses the cost model. All intangibles are amortised on a straight-line basis over their useful lives of between five and fifteen years', 'The entity uses the same policy for tangible and intangible assets'], 2,
      `A good note states the model, the method and the period. Valuation needs an active market and cannot rest on directors' judgement, and increases go to other comprehensive income.`,
      `Хорошее примечание называет модель, метод и срок. Оценка требует активного рынка и не может основываться на суждении директоров, а прирост идёт в прочий совокупный доход.`,
      `Yaxshi izoh model, usul va muddatni aytadi. Baholash faol bozor talab qiladi va direktorlar mulohazasiga tayana olmaydi, o'sish boshqa umumlashgan daromadga o'tadi.`),
    single(409, 'Which is a suitable accounting policy note for land and buildings?',
      ['Land and buildings are at cost and are written off over 50 years on a straight-line basis', 'Land and buildings are at cost and are not depreciated, as the directors expect their market value to rise', 'Land and buildings are at cost, and the buildings are written off over 50 years on a straight-line basis', 'The entity uses the same policy for land and buildings as for intangible assets'], 2,
      `Land is not depreciated, so the first answer is wrong. Buildings have a finite life, so a rising market value is no reason to skip depreciation.`,
      `Земля не амортизируется, поэтому первый ответ неверен. У зданий конечный срок, поэтому рост рыночной цены — не причина отказаться от амортизации.`,
      `Yer amortizatsiyalanmaydi, birinchi javob noto'g'ri. Binolar muddati cheklangan, bozor narxi o'sishi amortizatsiyani bekor qilmaydi.`),
    single(410, 'Which is a suitable accounting policy note for inventory?',
      ['Inventory is valued at the lower of total cost and total net realisable value', 'Inventory is valued at the lower of cost and net realisable value for each separate item', 'Inventory is valued at the higher of cost and net realisable value for each separate item', 'Inventory is valued at cost for each separate item'], 1,
      `IAS 2 compares cost and NRV item by item. Comparing totals could overstate inventory, and so would using the higher figure.`,
      `IAS 2 сравнивает стоимость и ЧСР по каждой позиции. Сравнение итогов может завысить запасы, как и выбор большей суммы.`,
      `IAS 2 qiymat va SSQ ni har bir modda bo'yicha solishtiradi. Jamlarni solishtirish zaxirani oshirib yuborishi mumkin, kattasini olish ham.`),
    matrix(411, 'State whether this statement is true or false.', TF, [
      { text: 'Non-adjusting events can be ignored when preparing the annual financial statements and supporting notes', correctIndex: F },
    ],
      `They do not change the figures, but if they are material they must be disclosed in a note.`,
      `Они не меняют цифры, но если существенны, должны быть раскрыты в примечании.`,
      `Ular raqamlarni o'zgartirmaydi, lekin muhim bo'lsa izohda ochilishi kerak.`),
    single(412, 'What should be disclosed in the notes about a non-adjusting event? (1) The nature of the event. (2) The names of those responsible. (3) The geographical location. (4) An estimate of the financial effect.',
      ['1 and 2', '1, 3 and 4', '2, 3 and 4', '1 and 4 only'], 3,
      `IAS 10 requires the nature of the event and an estimate of its financial effect, or a statement that no estimate can be made. Nothing else is required.`,
      `IAS 10 требует характер события и оценку финансового эффекта или заявление, что её сделать нельзя. Больше ничего не требуется.`,
      `IAS 10 voqea mohiyati va moliyaviy ta'sir bahosini yoki baho berib bo'lmasligini talab qiladi. Boshqa narsa kerak emas.`),
    matrix(413, 'For non-current assets, say whether each item should be disclosed in the notes.', ['Disclosed', 'Not disclosed'], [
      { text: 'A reconciliation of carrying amounts at the start and end of the period', correctIndex: 0 },
      { text: 'Useful lives of assets or depreciation rates used', correctIndex: 0 },
      { text: 'Increases in asset values from revaluations in the period', correctIndex: 0 },
      { text: 'Depreciation expense for the period', correctIndex: 0 },
    ],
      `All four are required. Three are part of the movements table, and the useful lives or rates are a narrative disclosure.`,
      `Все четыре требуются. Три входят в таблицу движения, а сроки или ставки — описательное раскрытие.`,
      `To'rttasi ham talab qilinadi. Uchtasi harakat jadvalida, muddat yoki stavkalar tavsifiy ochib berish.`),
    matrix(414, 'IFRS 18 requires certain items in the statement of profit or loss. With expenses classified by function, is each item presented there?', ['Presented', 'Not presented'], [
      { text: 'Revenue', correctIndex: 0 },
      { text: 'Closing inventory', correctIndex: 1 },
      { text: 'Interest expense', correctIndex: 0 },
      { text: 'Dividends paid', correctIndex: 1 },
      { text: 'Income tax expense', correctIndex: 0 },
      { text: 'Depreciation expense for the year', correctIndex: 1 },
    ],
      `Revenue, interest expense and income tax expense are presented. Closing inventory is in the statement of financial position, and dividends paid are in changes in equity. By function, depreciation is included in other headings and disclosed in the notes.`,
      `Выручка, процентный расход и расход по налогу показываются. Запасы на конец — в отчёте о финансовом положении, выплаченные дивиденды — в изменениях капитала. При функции амортизация входит в другие статьи и раскрывается в примечаниях.`,
      `Tushum, foiz xarajati va soliq xarajati ko'rsatiladi. Yakuniy zaxira moliyaviy holat hisobotida, to'langan dividendlar kapital o'zgarishlarida. Funksiya bo'yicha amortizatsiya boshqa moddalar ichida va izohlarda.`),
    single(415, 'Which statement about disclosure requirements is true?',
      ['They are only monetary', 'They are only narrative', 'They are both monetary and narrative', 'Disclosure notes are not part of the annual financial statements'], 2,
      `Notes can be figures, such as the depreciation charge, or words, such as accounting policies, and they form part of the financial statements.`,
      `Примечания могут быть цифрами, например амортизация, или словами, например учётная политика, и они — часть отчётности.`,
      `Izohlar raqam, masalan amortizatsiya, yoki so'z, masalan hisob siyosati bo'lishi mumkin va ular hisobot qismi.`),
    matrix(416, 'State whether this statement about property, plant and equipment disclosures is true or false.', TF, [
      { text: 'The estimated useful lives AND the depreciation rates used must both be disclosed', correctIndex: F },
    ],
      `Either is enough. Giving the rates tells users about the useful lives, and the other way round.`,
      `Достаточно одного. Ставки сообщают о сроках, и наоборот.`,
      `Bittasi yetarli. Stavkalar muddat haqida aytadi va aksincha.`),
    single(417, 'Which of these is NOT required to be disclosed for a provision?',
      ['The nature of the obligation', 'The expected timing of any payment', 'The name of the party owed', 'The uncertainties that may affect the amount'], 2,
      `IAS 37 asks for the nature, timing and uncertainties. It does not ask for the name of the party, which could also harm the entity's position.`,
      `IAS 37 требует характер, срок и неопределённости. Имя стороны не требуется, оно могло бы и навредить компании.`,
      `IAS 37 mohiyat, muddat va noaniqliklarni so'raydi. Tomon nomi talab qilinmaydi, u korxonaga zarar ham berishi mumkin.`),
    matrix(418, 'State whether this statement about provision disclosures is true or false.', TF, [
      { text: 'An entity need only state the carrying amount at the start and end of the period, with no reconciliation of the movement', correctIndex: F },
    ],
      `A reconciliation of the movement in the year is required as well as the two balances.`,
      `Требуется сверка движения за год, а не только два остатка.`,
      `Ikki qoldiqdan tashqari yil harakati solishtirishi ham talab qilinadi.`),
    single(419, 'Which of these must be disclosed for non-current assets? (1) The depreciation charge for the year. (2) The amortisation charge for the year. (3) The date of any revaluation. (4) Whether an independent valuer was used.',
      ['1, 2 and 3 only', '2, 3 and 4 only', '1, 3 and 4 only', '1, 2, 3 and 4'], 3,
      `All four are required. The charges are in the movement tables, and revaluations need the date and whether the valuer was independent.`,
      `Все четыре требуются. Начисления есть в таблицах движения, а для переоценки нужны дата и независимость оценщика.`,
      `To'rttasi talab qilinadi. Hisoblashlar harakat jadvallarida, qayta baholash uchun sana va baholovchi mustaqilligi kerak.`),
    single(420, 'How are intangible assets presented in the statement of financial position?',
      ['At the disposal proceeds value', 'At cost or valuation, less amortisation and impairment', 'At cost only, ignoring amortisation or impairment', 'At the amortisation amount only'], 1,
      `The carrying amount is cost or valuation, less amortisation to date and any impairment.`,
      `Балансовая стоимость — стоимость или оценка минус накопленная амортизация и обесценение.`,
      `Balans qiymati — qiymat yoki baho minus hozirgacha amortizatsiya va qadrsizlanish.`),
    single(421, 'A warranty provision note shows: brought forward $6,000; increase in provision $1,200; payments for warranty repairs ($2,900); carried forward $4,300. What is the warranty expense in the statement of profit or loss?',
      ['Debit of $1,200', 'Credit of $1,200', 'Credit of $1,700', 'Debit of $1,700'], 0,
      `The expense is the increase in the provision: Dr Warranty expense $1,200, Cr Provision. Payments use up the provision and are not a further expense.`,
      `Расход — рост резерва: Дт Расход на гарантию $1,200, Кт Резерв. Выплаты используют резерв и не являются новым расходом.`,
      `Xarajat rezerv o'sishi: Dt Kafolat xarajati $1,200, Kt Rezerv. To'lovlar rezervni ishlatadi, yangi xarajat emas.`),
    single(422, 'A draft note for property, plant and equipment shows cost, a revaluation of land and buildings, accumulated depreciation and additions, with no disposals. Which should be added to complete it? (1) The date of the revaluation. (2) Whether an independent valuer was used. (3) The carrying amount of land and buildings had they not been revalued. (4) The total carrying amount of each class at the start and end of the period.',
      ['1 and 4 only', '1, 2 and 3 only', '4 only', '1, 2, 3 and 4'], 3,
      `All four are needed. Items 1 to 3 are the revaluation disclosures, and the carrying amounts complete the table.`,
      `Нужны все четыре. Пункты 1-3 — раскрытия по переоценке, а балансовые суммы завершают таблицу.`,
      `To'rttasi kerak. 1-3 bandlar qayta baholash ochiqlari, balans qiymatlari jadvalni to'ldiradi.`),
    single(423, 'What should be disclosed in the notes for a material non-adjusting event?',
      ['Where the event took place', 'A letter from the company\'s lawyer', 'Nothing', 'The nature of the event and its estimated financial effect'], 3,
      `These are the two things IAS 10 asks for, so that the statements are not misleading.`,
      `Это две вещи, которые требует IAS 10, чтобы отчётность не вводила в заблуждение.`,
      `IAS 10 hisobot chalg'itmasligi uchun shu ikki narsani so'raydi.`),
    matrix(424, 'A company\'s year ended on 30 September. Its statements were approved on 12 January and issued on 20 February. Is each event adjusting or non-adjusting?', ['Adjusting', 'Non-adjusting'], [
      { text: 'A flood on 3 October destroyed a small amount of inventory costing $1,900', correctIndex: 1 },
      { text: 'A customer with a balance owing at 30 September was declared insolvent on 20 December', correctIndex: 0 },
      { text: 'Inventory valued at cost of $900 at 30 September was sold for $720 on 11 November', correctIndex: 0 },
      { text: 'An equity dividend of 5 cents per share was declared on 1 December', correctIndex: 1 },
    ],
      `The flood is a new condition after the year end. The insolvency and the sale below cost are evidence about balances at the year end. A dividend declared after the year end is non-adjusting.`,
      `Наводнение — новое условие после конца года. Неплатёжеспособность и продажа ниже стоимости — свидетельства об остатках на конец года. Дивиденд, объявленный после конца года, — некорректирующий.`,
      `Toshqin yil oxiridan keyingi yangi holat. Bankrotlik va tannarxdan past sotuv yil oxiri qoldiqlari haqida dalil. Yil oxiridan keyin e'lon qilingan dividend tuzatmaydigan.`),
    single(425, 'Which statements are correct under IAS 10? (1) Details of all adjusting events must be disclosed in the notes. (2) A material loss on selling, after the reporting date, inventory held at cost must be reflected in the statements. (3) If the market value of property, plant and equipment falls materially after the reporting date, details must be disclosed. (4) Events after the reporting period are those between the reporting date and the date the statements are approved.',
      ['1 and 2', '1, 3 and 4', '2 and 3 only', '2, 3 and 4'], 3,
      `Statement 1 is false, because adjusting events change the figures and are not written up in the notes. The others are true.`,
      `Утверждение 1 неверно: корректирующие события меняют цифры и не описываются в примечаниях. Остальные верны.`,
      `1-bayonot noto'g'ri: tuzatuvchi voqealar raqamlarni o'zgartiradi, izohda yozilmaydi. Qolganlari to'g'ri.`),
    single(426, 'A company\'s year ended on 30 September, and its statements were approved on 14 December. (1) On 13 December a fire destroyed all inventory, and the directors consider the business no longer a going concern. (2) A customer owing a balance at 30 September was declared bankrupt on 12 December. (3) An equity dividend of 6 cents per share was declared on 1 December. (4) Inventory valued at cost of $900 was sold for $720 on 11 November. Which would NOT result in amounts being adjusted?',
      ['2 and 3', '3 only', '3 and 4', '1 and 3'], 1,
      `Items 2 and 4 are adjusting. Item 1 is a non-adjusting event, but because the going concern basis no longer applies, the basis of accounting changes and the figures are adjusted. Only the dividend leaves amounts unchanged.`,
      `Пункты 2 и 4 корректирующие. Пункт 1 некорректирующий, но без непрерывности меняется основа учёта, и цифры корректируются. Только дивиденд оставляет суммы без изменений.`,
      `2 va 4-bandlar tuzatuvchi. 1-band tuzatmaydigan, lekin uzluksizlik yo'qligi uchun asos o'zgaradi va raqamlar tuzatiladi. Faqat dividend summalarni o'zgartirmaydi.`),
    single(427, 'A company has a year end of 31 January. Which of these, happening before the statements are approved, are adjusting events? (1) It paid an equity dividend of $12,000 on 28 February, proposed on 20 January. (2) On 15 February it was notified of a claim about a faulty product sold in January. (3) On 5 February it learned that a major credit customer was insolvent.',
      ['1, 2 and 3', '2 and 3', '1 and 3', '2 only'], 1,
      `Items 2 and 3 give evidence of conditions at the year end. IAS 10 specifically prevents adjusting for a dividend, even one proposed before the year end and paid after.`,
      `Пункты 2 и 3 — свидетельства условий на конец года. IAS 10 прямо запрещает корректировку на дивиденд, даже предложенный до конца года и выплаченный после.`,
      `2 va 3-bandlar yil oxiridagi holat dalili. IAS 10 yil oxirigacha taklif qilinib, keyin to'langan dividendni ham tuzatishni taqiqlaydi.`),
    single(428, 'Between the year end of 30 November and approval on 31 January a company learned that (1) a customer has started legal action over faulty products supplied in December, and (2) a former employee is suing for unfair dismissal in November. Both claims are likely to succeed and are material. How are they reported?',
      ['Provide for claim 1; nothing for claim 2', 'Provide for both claims', 'Neither provided for nor disclosed', 'Disclose claim 1; provide for claim 2'], 3,
      `Claim 1 arises from a December supply, after the year end, so it is non-adjusting and disclosed because it is material. Claim 2 arises from an event before the year end, so it is adjusting and provided for.`,
      `Иск 1 из поставки в декабре, после конца года, он некорректирующий и раскрывается, так как существенен. Иск 2 из события до конца года, он корректирующий, и создаётся резерв.`,
      `1-da'vo dekabr yetkazishidan, yil oxiridan keyin, tuzatmaydigan va muhim bo'lgani uchun ochiladi. 2-da'vo yil oxirigacha voqeadan, tuzatuvchi va rezerv tuziladi.`),
    single(429, 'A trader sells computers to individuals. Which of these is recognised as revenue?',
      ['Payment received from a customer for computers delivered two weeks ago', 'The sale of the trader\'s delivery van to a relative for cash', 'A competitor that ran out of an item asked the trader to fulfil a sale, and the trader delivered the goods', 'A refundable $100 deposit for a computer the customer may order next week'], 2,
      `The goods were delivered under a contract, so the obligation is satisfied. The van is a disposal, the deposit relates to nothing yet delivered, and the receipt only settles an earlier sale.`,
      `Товар поставлен по договору, обязанность исполнена. Фургон — выбытие, депозит не связан с поставкой, а поступление лишь закрывает прошлую продажу.`,
      `Tovar shartnoma bo'yicha yetkazildi, majburiyat bajarildi. Furgon chiqish, depozit hech narsaga tegishli emas, tushum faqat oldingi sotuvni yopadi.`),
    number(430, 'A company acts as an agent for another business and arranged a sale at $90,000 on 1 August. It is entitled to 10% commission on receipt of cash, and the customer paid on 28 September. What revenue is recognised for the year ended 30 September?', 9000, '$9,000',
      `An agent's revenue is only its commission: $90,000 x 10% = $9,000. The other $81,000 is a liability to the principal until paid over.`,
      `Выручка агента — только комиссия: $90,000 x 10% = $9,000. Остальные $81,000 — обязательство перед принципалом до перечисления.`,
      `Agent tushumi faqat komissiya: $90,000 x 10% = $9,000. Qolgan $81,000 o'tkazilguncha asosiy tomonga majburiyat.`),
    number(431, 'A company sells machines at $800, installation at $120 and a one-year support agreement at $180. A customer bought all three on 1 October. The machine was delivered and installed that day, and support began. How much revenue is recognised for the year ended 31 December?', 965, '$965',
      `The machine and installation are complete: $800 + $120 = $920. Support runs over time, so three months is 3/12 x $180 = $45. The total is $965.`,
      `Машина и установка завершены: $800 + $120 = $920. Поддержка идёт во времени, три месяца: 3/12 x $180 = $45. Всего $965.`,
      `Mashina va o'rnatish tugallangan: $800 + $120 = $920. Xizmat vaqt davomida, uch oy: 3/12 x $180 = $45. Jami $965.`),
    single(432, 'Which item has been correctly included in a company\'s revenue for the year ended 31 March?',
      ['It negotiated a $240,000 sale for a client at 10% commission, and recognised $240,000', 'It began a three-year consultancy contract for $360,000 on 1 July, and recognised $120,000', 'It bought goods for $60,000 on 1 November and sold them for $90,000 on 20 January, and recognised $90,000', 'It bought goods for $30,000 on 1 December and sold them for $60,000 on 10 January, and recognised $30,000'], 2,
      `Selling goods for $90,000 gives revenue of $90,000. The first should be commission of $24,000. Nine months of the contract is $90,000, not $120,000. The last should be $60,000, not the profit.`,
      `Продажа за $90,000 даёт выручку $90,000. В первом случае нужна комиссия $24,000. Девять месяцев договора — $90,000, а не $120,000. В последнем нужно $60,000, а не прибыль.`,
      `$90,000 ga sotish $90,000 tushum beradi. Birinchisida $24,000 komissiya bo'lishi kerak. Shartnomaning to'qqiz oyi $90,000, $120,000 emas. Oxirgisida foyda emas, $60,000.`),
    single(433, 'Which of these is NOT part of the five-step approach in IFRS 15?',
      ['Identify the contract', 'All contracts must be in writing', 'Recognise revenue when a performance obligation is satisfied', 'Allocate the total price between the performance obligations'], 1,
      `A contract does not have to be written. Many businesses prefer it, but it is not a step in the approach.`,
      `Договор не обязан быть письменным. Многие это предпочитают, но это не шаг модели.`,
      `Shartnoma yozma bo'lishi shart emas. Ko'pchilik shuni afzal ko'radi, lekin bu bosqich emas.`),
    matrix(434, 'Is each of these an acceptable basis for recognising revenue?', TF, [
      { text: 'On any reasonable basis', correctIndex: F },
      { text: 'At a point in time', correctIndex: T },
      { text: 'Annually', correctIndex: F },
      { text: 'Over a period of time', correctIndex: T },
    ],
      `Revenue is recognised when an obligation is satisfied: at a point in time, usually for goods, or over a period of time, usually for services.`,
      `Выручка признаётся при исполнении обязанности: в момент, обычно для товаров, или в течение времени, обычно для услуг.`,
      `Tushum majburiyat bajarilganda tan olinadi: bir paytda, odatda tovarlar uchun, yoki vaqt davomida, odatda xizmatlar uchun.`),
    single(435, 'Which item complies with IFRS 15 for inclusion in a company\'s revenue for the year ended 30 September?',
      ['A free sample with a normal price of $1,200 was given to a new customer, and $1,200 was included', 'An annual magazine subscription for $3,600 was sold, with the first issue sent on 1 November, and $3,600 was included', 'Goods with a list price of $6,000 were supplied on 1 December with a trade discount of 10%, and $5,400 was included', 'Goods with a list price of $12,000 were sold on 1 February with a 2% settlement discount that the customer was not expected to take, and $11,760 was recorded'], 2,
      `Trade discount always comes off, so $5,400 is right. A free sample earns nothing. Only 11 of the 12 subscription months have passed. The settlement discount should not be deducted if it is not expected to be taken.`,
      `Торговая скидка вычитается всегда, поэтому $5,400 верно. Бесплатный образец ничего не приносит. Прошло только 11 из 12 месяцев подписки. Скидка за раннюю оплату не вычитается, если её не ожидают.`,
      `Savdo chegirmasi doim ayiriladi, $5,400 to'g'ri. Bepul namuna hech narsa bermaydi. Obunaning 12 oyidan faqat 11 tasi o'tgan. To'lov chegirmasi kutilmasa ayirilmaydi.`),
  ];

  if (typeof module !== 'undefined') module.exports = questions;
  else ((globalThis.ACCA ??= {}).questions ??= {})[TOPIC] = questions;
})();
